// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAccounts Accounts owned by the caller
	// (GET /accounts)
	GetAccounts(ctx context.Context, request GetAccountsRequestObject) (GetAccountsResponseObject, error)

	// (GET /accounts/{accountId})
	GetAccountsAccountId(ctx context.Context, request GetAccountsAccountIdRequestObject) (GetAccountsAccountIdResponseObject, error)
	// GetAccountsAccountIdActivity Activity timeline (event → prediction → intent → eligibility → risk → execution → fill → reconciliation)
	// (GET /accounts/{accountId}/activity)
	GetAccountsAccountIdActivity(ctx context.Context, request GetAccountsAccountIdActivityRequestObject) (GetAccountsAccountIdActivityResponseObject, error)
	// GetAccountsAccountIdBuyingPower Buying power computed now by the backend (PART 25); never cached as truth
	// (GET /accounts/{accountId}/buying-power)
	GetAccountsAccountIdBuyingPower(ctx context.Context, request GetAccountsAccountIdBuyingPowerRequestObject) (GetAccountsAccountIdBuyingPowerResponseObject, error)
	// GetAccountsAccountIdExport Export journal transactions and fills as CSV or JSON (PART 202)
	// (GET /accounts/{accountId}/export)
	GetAccountsAccountIdExport(ctx context.Context, request GetAccountsAccountIdExportRequestObject) (GetAccountsAccountIdExportResponseObject, error)
	// GetAccountsAccountIdHoldings Holdings with units, USD mark, basis and unrealized P&L
	// (GET /accounts/{accountId}/holdings)
	GetAccountsAccountIdHoldings(ctx context.Context, request GetAccountsAccountIdHoldingsRequestObject) (GetAccountsAccountIdHoldingsResponseObject, error)
	// GetAccountsAccountIdLedgerTransactions Journal transactions for the account (append-only history), newest first
	// (GET /accounts/{accountId}/ledger/transactions)
	GetAccountsAccountIdLedgerTransactions(ctx context.Context, request GetAccountsAccountIdLedgerTransactionsRequestObject) (GetAccountsAccountIdLedgerTransactionsResponseObject, error)
	// GetAdminAccounts Search accounts (operator roles)
	// (GET /admin/accounts)
	GetAdminAccounts(ctx context.Context, request GetAdminAccountsRequestObject) (GetAdminAccountsResponseObject, error)
	// PostAdminAccountsAccountIdStatus Freeze / restrict / reactivate an account (reason required; audited; no balance editing exists)
	// (POST /admin/accounts/{accountId}/status)
	PostAdminAccountsAccountIdStatus(ctx context.Context, request PostAdminAccountsAccountIdStatusRequestObject) (PostAdminAccountsAccountIdStatusResponseObject, error)
	// GetAdminActions Pending and recent controlled administrative actions
	// (GET /admin/actions)
	GetAdminActions(ctx context.Context, request GetAdminActionsRequestObject) (GetAdminActionsResponseObject, error)
	// PostAdminActions Propose a controlled action (reason required; step-up)
	// (POST /admin/actions)
	PostAdminActions(ctx context.Context, request PostAdminActionsRequestObject) (PostAdminActionsResponseObject, error)
	// PostAdminActionsActionIdDecision Approve or reject a proposed action (approver ≠ proposer; step-up)
	// (POST /admin/actions/{actionId}/{decision})
	PostAdminActionsActionIdDecision(ctx context.Context, request PostAdminActionsActionIdDecisionRequestObject) (PostAdminActionsActionIdDecisionResponseObject, error)
	// GetAdminGates Production capability gates for this environment
	// (GET /admin/gates)
	GetAdminGates(ctx context.Context, request GetAdminGatesRequestObject) (GetAdminGatesResponseObject, error)
	// PostAdminGatesCapabilityAction Propose / approve / activate / suspend / resume / revoke a gate (dual control; step-up)
	// (POST /admin/gates/{capability}/{action})
	PostAdminGatesCapabilityAction(ctx context.Context, request PostAdminGatesCapabilityActionRequestObject) (PostAdminGatesCapabilityActionResponseObject, error)
	// PostAdminInstrumentsInstrumentIdStatus Change instrument status (ACTIVE / CLOSE_ONLY / RESTRICTED / HALTED / DELISTING / DELISTED)
	// (POST /admin/instruments/{instrumentId}/status)
	PostAdminInstrumentsInstrumentIdStatus(ctx context.Context, request PostAdminInstrumentsInstrumentIdStatusRequestObject) (PostAdminInstrumentsInstrumentIdStatusResponseObject, error)

	// (GET /admin/kill-switches)
	GetAdminKillSwitches(ctx context.Context, request GetAdminKillSwitchesRequestObject) (GetAdminKillSwitchesResponseObject, error)
	// PostAdminKillSwitches Activate (fast, single operator) or release (step-up; SEVERE needs an approved admin action) a kill switch
	// (POST /admin/kill-switches)
	PostAdminKillSwitches(ctx context.Context, request PostAdminKillSwitchesRequestObject) (PostAdminKillSwitchesResponseObject, error)
	// GetAdminProviders Provider health and verification labels
	// (GET /admin/providers)
	GetAdminProviders(ctx context.Context, request GetAdminProvidersRequestObject) (GetAdminProvidersResponseObject, error)

	// (GET /admin/reconciliation/records)
	GetAdminReconciliationRecords(ctx context.Context, request GetAdminReconciliationRecordsRequestObject) (GetAdminReconciliationRecordsResponseObject, error)
	// PostAdminReconciliationRecordsRecordIdResolve Resolve a mismatch (reason + evidence; material resolutions require an approved admin action; corrections post a compensating journal transaction)
	// (POST /admin/reconciliation/records/{recordId}/resolve)
	PostAdminReconciliationRecordsRecordIdResolve(ctx context.Context, request PostAdminReconciliationRecordsRecordIdResolveRequestObject) (PostAdminReconciliationRecordsRecordIdResolveResponseObject, error)
	// GetAssets Registered assets with chain, mint, decimals and safety status
	// (GET /assets)
	GetAssets(ctx context.Context, request GetAssetsRequestObject) (GetAssetsResponseObject, error)
	// GetAuthCallback OIDC callback; establishes a server-side session cookie
	// (GET /auth/callback)
	GetAuthCallback(ctx context.Context, request GetAuthCallbackRequestObject) (GetAuthCallbackResponseObject, error)
	// GetAuthLogin Begin OIDC login (authorization-code + PKCE); redirects to the identity provider
	// (GET /auth/login)
	GetAuthLogin(ctx context.Context, request GetAuthLoginRequestObject) (GetAuthLoginResponseObject, error)
	// PostAuthLogout Revoke the current session
	// (POST /auth/logout)
	PostAuthLogout(ctx context.Context, request PostAuthLogoutRequestObject) (PostAuthLogoutResponseObject, error)
	// GetEventsStream Server-sent events for balances, orders, deposits and agent state (not authoritative)
	// (GET /events/stream)
	GetEventsStream(ctx context.Context, request GetEventsStreamRequestObject) (GetEventsStreamResponseObject, error)

	// (GET /funding/deposits)
	GetFundingDeposits(ctx context.Context, request GetFundingDepositsRequestObject) (GetFundingDepositsResponseObject, error)
	// PostFundingDeposits Start a fiat-to-USDC funding session (redirect success never credits money — PART 162)
	// (POST /funding/deposits)
	PostFundingDeposits(ctx context.Context, request PostFundingDepositsRequestObject) (PostFundingDepositsResponseObject, error)

	// (GET /funding/deposits/{depositId})
	GetFundingDepositsDepositId(ctx context.Context, request GetFundingDepositsDepositIdRequestObject) (GetFundingDepositsDepositIdResponseObject, error)

	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetInstruments Tradable instruments (V1 spot pairs) with status
	// (GET /instruments)
	GetInstruments(ctx context.Context, request GetInstrumentsRequestObject) (GetInstrumentsResponseObject, error)

	// (GET /instruments/{instrumentId})
	GetInstrumentsInstrumentId(ctx context.Context, request GetInstrumentsInstrumentIdRequestObject) (GetInstrumentsInstrumentIdResponseObject, error)
	// GetIntents Intents for an account, newest first
	// (GET /intents)
	GetIntents(ctx context.Context, request GetIntentsRequestObject) (GetIntentsResponseObject, error)
	// PostIntents Submit a typed trade intent (manual trading entry point; PART 35)
	// (POST /intents)
	PostIntents(ctx context.Context, request PostIntentsRequestObject) (PostIntentsResponseObject, error)

	// (GET /intents/{intentId})
	GetIntentsIntentId(ctx context.Context, request GetIntentsIntentIdRequestObject) (GetIntentsIntentIdResponseObject, error)
	// PostIntentsIntentIdCancel Request cancellation (CANCEL_REQUESTED; only external confirmation yields CANCELLED — PART 227)
	// (POST /intents/{intentId}/cancel)
	PostIntentsIntentIdCancel(ctx context.Context, request PostIntentsIntentIdCancelRequestObject) (PostIntentsIntentIdCancelResponseObject, error)
	// GetMe Current principal and the accounts it may act on
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)

	// (GET /orders)
	GetOrders(ctx context.Context, request GetOrdersRequestObject) (GetOrdersResponseObject, error)

	// (GET /orders/{orderId})
	GetOrdersOrderId(ctx context.Context, request GetOrdersOrderIdRequestObject) (GetOrdersOrderIdResponseObject, error)
	// PostQuotesPreview Non-binding quote preview with full fee disclosure (no money moves, no reservation)
	// (POST /quotes/preview)
	PostQuotesPreview(ctx context.Context, request PostQuotesPreviewRequestObject) (PostQuotesPreviewResponseObject, error)
	// GetReadyz Ready when the database is reachable and configuration validated; never reports provider liveness as readiness
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
	// GetSessions List the caller's sessions (device listing)
	// (GET /sessions)
	GetSessions(ctx context.Context, request GetSessionsRequestObject) (GetSessionsResponseObject, error)
	// DeleteSessionsSessionId Revoke one of the caller's sessions
	// (DELETE /sessions/{sessionId})
	DeleteSessionsSessionId(ctx context.Context, request DeleteSessionsSessionIdRequestObject) (DeleteSessionsSessionIdResponseObject, error)
	// GetVersion Build version and non-secret configuration hash (PART 222)
	// (GET /version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)
	// PostWebhooksProvider Provider webhook ingestion (signature-verified, persisted before processing, idempotent — PART 30)
	// (POST /webhooks/{provider})
	PostWebhooksProvider(ctx context.Context, request PostWebhooksProviderRequestObject) (PostWebhooksProviderResponseObject, error)
	// PostWithdrawals Request a withdrawal (requires step-up; the WITHDRAWALS capability is DISABLED in V1 — PART 94)
	// (POST /withdrawals)
	PostWithdrawals(ctx context.Context, request PostWithdrawalsRequestObject) (PostWithdrawalsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetAccounts operation middleware
func (sh *strictHandler) GetAccounts(w http.ResponseWriter, r *http.Request) {
	var request GetAccountsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetAccounts(ctx, request.(GetAccountsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetAccounts")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetAccountsResponseObject); ok {
		if err := validResponse.VisitGetAccountsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

